#!/bin/bash
# Run MMIX tests using Verilator simulation
# This tests the MMIX processor generated by isacomp

SCRIPT_DIR=$(cd "$(dirname "$0")" && pwd)
PROJECT_ROOT=$(cd "$SCRIPT_DIR/../../.." && pwd)
cd "$SCRIPT_DIR"

VERILOG_DIR="."
TEST_DIR="../../../isa/mmix/mmix-tests"

echo "MMIX Verilator Test Runner"
echo "=========================="

# Check for Verilator
if ! command -v verilator &> /dev/null; then
    echo "ERROR: Verilator not found. Please install Verilator."
    exit 1
fi

# Generate MMIX processor if needed
if [ ! -f "${VERILOG_DIR}/mmix_complete.v" ]; then
    echo "Generating MMIX processor..."
    python3 ../../../isa/mmix/generators/generate_mmix_complete.py --backend verilog --output-dir "$SCRIPT_DIR"
    if [ $? -ne 0 ]; then
        echo "ERROR: Failed to generate MMIX processor"
        exit 1
    fi
fi

# Compile with Verilator if needed or if source changed
RECOMPILE=0
if [ ! -f "${VERILOG_DIR}/test_mmix" ]; then
    RECOMPILE=1
elif [ "${VERILOG_DIR}/mmix_complete.v" -nt "${VERILOG_DIR}/test_mmix" ]; then
    RECOMPILE=1
elif [ "${VERILOG_DIR}/mmix_complete_tb.sv" -nt "${VERILOG_DIR}/test_mmix" ]; then
    RECOMPILE=1
fi

if [ $RECOMPILE -eq 1 ]; then
    echo "Compiling MMIX processor with Verilator..."

    verilator --timing --exe --binary \
        -Wno-fatal -Wno-WIDTHTRUNC -Wno-WIDTHEXPAND -Wno-TIMESCALEMOD \
        -o test_mmix mmix_complete.v mmix_complete_tb.sv 2>&1

    if [ $? -ne 0 ]; then
        echo "ERROR: Verilator compilation failed!"
        exit 1
    fi

    # Move binary from obj_dir
    if ! mv obj_dir/test_mmix . 2>/dev/null; then
        echo "ERROR: Failed to move Verilator sim binary"
        exit 1
    fi
    rm -rf obj_dir
fi

# Run Python test script with absolute path to simulator
echo ""
echo "Running MMIX tests..."
SIMULATOR_ABS="$SCRIPT_DIR/test_mmix"
python3 ${TEST_DIR}/run_mmix_tests.py --processor-dir "$SCRIPT_DIR" --simulator "${SIMULATOR_ABS}"

exit $?
